{
  "technical_and_design_decisions": [
    "Align the XD codebase with Spring Framework 6.0 and Java 17+ as stated in the specification, and upgrade Spring Batch to the release that contains the execution-context/job-launch decoupling fix (U4).",
    "U1: Migrate wiki pages into the project repository as Markdown/AsciiDoc under a /docs folder so documentation is versioned and tagged together with code releases; wire docs into the existing build so they publish with each tag.",
    "U2: Use Spring externalized configuration (properties/YAML file on the classpath or a well-known location) holding the Hadoop namenode URI, loaded automatically at DSL session startup; explicit in-session settings still override the file.",
    "U3: Implement the jdbchdfs passthrough mode as a non-chunk Tasklet-based job variant that streams JDBC results straight to HDFS, bypassing reader/processor/writer chunk overhead; mode selectable via a job/module option.",
    "U4: Replace the XD-2486 workaround with the official Spring Batch fix by upgrading the Batch dependency and refactoring the job launch lifecycle integration so the execution context is no longer serialized/shared across launches.",
    "U5: Extend module deployment to detect annotation-based job modules (@Configuration / @EnableBatchProcessing classes) in addition to XML, fixing classpath scanning and bean registration in the module classloader so Java Config jobs deploy and launch correctly.",
    "U6: Design a pluggable container/runtime SPI (deploy, undeploy, status, scale operations) with the Lattice/Diego Receptor API as one implementation, keeping XD core code dependent only on the SPI interfaces.",
    "U7: Add a shortDescription field to module metadata (module descriptor/properties), surface it in module listing/info commands, and update all shipped module docs/metadata.",
    "U8: Extend the shell processor to resolve hdfs:// script locations via the existing HDFS file system abstraction, copy the Python script to a local working directory at runtime, execute it with the local Python runtime, and pipe stdout/stderr back into XD message channels."
  ],
  "assumptions": [
    "A single developer performs all work; estimates are effort in workdays, not calendar duration.",
    "The existing Spring XD codebase, its build system, CI pipeline, and development environment are already available and functional.",
    "A Hadoop/HDFS test environment (or HDFS mini-cluster for tests) is available for U2, U3, and U8 integration testing.",
    "The Spring Batch release containing the execution-context decoupling fix is already published; XD only needs to consume it (no changes required inside Spring Batch itself by this developer).",
    "A Python runtime is available on the target runtime cells (CF/Lattice/Diego) for U8.",
    "Wiki content volume is moderate (roughly 40-60 pages) and can be converted semi-automatically.",
    "No new UI development is required; existing shell/DSL and admin tooling are extended only.",
    "Estimates include design, implementation, unit testing, and developer-level documentation per activity; cross-cutting integration testing and release packaging are separate activities."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Overall analysis, design and increment planning",
      "activity_description": "Analyze the eight user stories against the existing XD codebase, confirm impacted components (DSL, batch jobs, module subsystem, runtime deployers, docs), define the design approach per story, and plan the increment.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A2",
      "activity_name": "U1 - Migrate wiki into project repository",
      "activity_description": "Export existing wiki content, convert pages to Markdown/AsciiDoc under /docs, restructure navigation and links, integrate docs into the build/tagging process, and validate rendering.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A3",
      "activity_name": "U2 - Hadoop namenode configuration file",
      "activity_description": "Define the config file format and lookup order, implement automatic loading of namenode settings at DSL session startup with override support, add unit/integration tests, and document the option.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A4",
      "activity_name": "U3 - jdbchdfs passthrough batch job",
      "activity_description": "Implement a passthrough (non-chunk, tasklet-based) variant of the jdbchdfs job that streams JDBC results directly to HDFS, add a mode option, write tests against an HDFS mini-cluster, and update module docs.",
      "most_likely_effort": 7
    },
    {
      "activity_id": "A5",
      "activity_name": "U4 - Upgrade Spring Batch and refactor XD-2486 workaround",
      "activity_description": "Upgrade the Spring Batch dependency to the release containing the execution-context/job-launch decoupling fix, remove and refactor the XD-2486 workaround, adapt launch lifecycle code, and run regression tests for job launching and serialization.",
      "most_likely_effort": 9
    },
    {
      "activity_id": "A6",
      "activity_name": "U5 - Support Java Config-based custom job modules",
      "activity_description": "Diagnose the 'job does not exist' deployment/launch error, extend module packaging/scanning and the module classloader to detect and register @Configuration-based job modules, verify with the reported scenario, and add tests and documentation.",
      "most_likely_effort": 9
    },
    {
      "activity_id": "A7",
      "activity_name": "U6 - Pluggable runtime SPI and Receptor API PoC",
      "activity_description": "Design a general pluggable SPI for container/runtime integration (deploy, undeploy, status), implement the SPI core and a Receptor API (Lattice/Diego) reference implementation, and validate the PoC end to end.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "A7b",
      "activity_name": "U7 - Add shortDescription to module metadata and docs",
      "activity_description": "Add shortDescription to the module descriptor/metadata model, expose it in module info/listing output, and update all shipped module documentation files with the new field, plus tests.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A8",
      "activity_name": "U8 - Execute Python script hosted on HDFS via shell processor",
      "activity_description": "Extend the shell processor to resolve hdfs:// script paths, copy/stream the Python script from HDFS to the local runtime working directory, execute it with the Python runtime, and route output back into XD channels; add tests and docs.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A9",
      "activity_name": "Cross-cutting integration and system testing",
      "activity_description": "Run end-to-end integration tests across all stories (DSL sessions, batch jobs, module deployment, runtime deployers, HDFS integration), fix defects found, and verify regressions from the Batch upgrade.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A10",
      "activity_name": "Documentation consolidation and release packaging",
      "activity_description": "Consolidate user and reference documentation for all new features, update changelog/readme, and package the increment (tagged build) for release.",
      "most_likely_effort": 3
    }
  ],
  "reported_total": {
    "most_likely_effort": 77
  }
}

